from math import gcd
from typing import NamedTuple

class PrimitiveTriple(NamedTuple):
    a: int; b: int; c: int

def is_primitive_triple(t: PrimitiveTriple) -> bool:
    a, b, c = t
    return (a**2 + b**2 == c**2 and a > 0 and b > 0 and c > 0
            and gcd(a, b) == 1 and a % 2 == 1)

def berggren_left(t: PrimitiveTriple) -> PrimitiveTriple:
    a, b, c = t
    return PrimitiveTriple(a-2*b+2*c, 2*a-b+2*c, 2*a-2*b+3*c)

def berggren_mid(t: PrimitiveTriple) -> PrimitiveTriple:
    a, b, c = t
    return PrimitiveTriple(a+2*b+2*c, 2*a+b+2*c, 2*a+2*b+3*c)

def berggren_right(t: PrimitiveTriple) -> PrimitiveTriple:
    a, b, c = t
    return PrimitiveTriple(-a+2*b+2*c, -2*a+b+2*c, -2*a+2*b+3*c)

STEPS = {'left': berggren_left, 'mid': berggren_mid, 'right': berggren_right}
ROOT = PrimitiveTriple(3, 4, 5)

queue = [(ROOT, 'root')]
visited = []
for depth in range(3):
    nq = []
    for t, path in queue:
        visited.append((path, t))
        for name, fn in STEPS.items():
            nq.append((fn(t), f'{path}.{name}'))
    queue = nq

all_ok = all(is_primitive_triple(t) for _, t in visited)
print(f'Checked {len(visited)} triples. All invariants preserved: {all_ok}')

