from typing import NamedTuple

class PrimitiveTriple(NamedTuple):
    a: int; b: int; c: int

def berggren_left(t): a,b,c=t; return PrimitiveTriple(a-2*b+2*c,2*a-b+2*c,2*a-2*b+3*c)
def berggren_mid(t): a,b,c=t; return PrimitiveTriple(a+2*b+2*c,2*a+b+2*c,2*a+2*b+3*c)
def berggren_right(t): a,b,c=t; return PrimitiveTriple(-a+2*b+2*c,-2*a+b+2*c,-2*a+2*b+3*c)

def generate_all(t, depth):
    if depth == 0: return [t]
    result = [t]
    for fn in [berggren_left, berggren_mid, berggren_right]:
        result.extend(generate_all(fn(t), depth - 1))
    return result

triples = generate_all(PrimitiveTriple(3, 4, 5), 5)
print(f'Generated {len(triples)} triples (depth <= 5).')
print(f'Unique triples: {len(set(triples))}.')
print(f'All distinct: {len(triples) == len(set(triples))}')

